#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, a, b, c;
    cin >> n >> a >> b >> c;

    vector<int> dp(n + 1, -1);
    dp[0] = 0;

    for (int i = 1; i <= n; ++i) {
        for (int length : {a, b, c}) {
            if (i >= length && dp[i - length] != -1) {
                dp[i] = max(dp[i], dp[i - length] + 1);
            }
        }
    }

    cout << dp[n];
    return 0;
}

